0017|int main(int argc, char **argv) {
0018|    if (argc == 2 && strcmp(argv[1], "--abi") == 0) {
0019|        struct seccomp_notif_sizes sizes;
0020|        if (syscall(SYS_seccomp, SECCOMP_GET_NOTIF_SIZES, 0, &sizes) < 0) return 126;
0021|        printf("{\"policy_version\":3,\"notif_size\":%u,\"response_size\":%u,\"recv\":%lu,\"send\":%lu,\"valid\":%lu,\"addfd\":%lu}\n",
0022|               sizes.seccomp_notif, sizes.seccomp_notif_resp,
0023|               (unsigned long)SECCOMP_IOCTL_NOTIF_RECV, (unsigned long)SECCOMP_IOCTL_NOTIF_SEND,
0024|               (unsigned long)SECCOMP_IOCTL_NOTIF_ID_VALID, (unsigned long)SECCOMP_IOCTL_NOTIF_ADDFD);
0025|        return 0;
0026|    }
0027|    const char *value = getenv("GUARDIAN_BROKER_FD");
0028|    char *end = NULL;
0029|    long channel = value ? strtol(value, &end, 10) : -1;
0030|    if (argc < 2 || !value || !end || *end || channel <= 2 || channel > INT_MAX) return 126;
0031|    struct sock_filter code[] = {
0032|        BPF_STMT(BPF_LD | BPF_W | BPF_ABS, offsetof(struct seccomp_data, arch)),
0033|        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, AUDIT_ARCH_X86_64, 1, 0),
0034|        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_KILL_PROCESS),
0035|        BPF_STMT(BPF_LD | BPF_W | BPF_ABS, offsetof(struct seccomp_data, nr)),
0036|        BPF_JUMP(BPF_JMP | BPF_JSET | BPF_K, 0x40000000U, 0, 1),
0037|        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ERRNO | ENOSYS),
0038|        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_seccomp, 0, 5),
0039|        BPF_STMT(BPF_LD | BPF_W | BPF_ABS, offsetof(struct seccomp_data, args[0])),
0040|        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SECCOMP_GET_ACTION_AVAIL, 2, 0),
0041|        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SECCOMP_GET_NOTIF_SIZES, 1, 0),
0042|        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_USER_NOTIF),
0043|        BPF_STMT(BPF_LD | BPF_W | BPF_ABS, offsetof(struct seccomp_data, nr)),
0044|        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_prctl, 0, 4),
0045|        BPF_STMT(BPF_LD | BPF_W | BPF_ABS, offsetof(struct seccomp_data, args[0])),
0046|        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, PR_SET_SECCOMP, 0, 1),
0047|        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_USER_NOTIF),
0048|        BPF_STMT(BPF_LD | BPF_W | BPF_ABS, offsetof(struct seccomp_data, nr)),
0049|        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_ptrace, 0, 1),
0050|        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_USER_NOTIF),
0051|        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_connect, 0, 1),
0052|        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_USER_NOTIF),
0053|        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_open, 0, 1),
0054|        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_USER_NOTIF),
0055|        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_openat, 0, 1),
0056|        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_USER_NOTIF),
0057|        BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, SYS_openat2, 0, 1),
0058|        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_USER_NOTIF),
0059|        BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW)
0060|    };
0061|    struct sock_fprog program = { .len = sizeof(code) / sizeof(code[0]), .filter = code };
0062|    if (prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) < 0) return 126;
0063|    int listener = syscall(SYS_seccomp, SECCOMP_SET_MODE_FILTER, SECCOMP_FILTER_FLAG_NEW_LISTENER, &program);
0064|    if (listener < 0) return 126;
0065|    char control[CMSG_SPACE(sizeof(int))] = {0};
0066|    struct iovec data = { .iov_base = "GNF1", .iov_len = 4 };
0067|    struct msghdr message = { .msg_iov = &data, .msg_iovlen = 1,
0068|                              .msg_control = control, .msg_controllen = sizeof(control) };
0069|    struct cmsghdr *header = CMSG_FIRSTHDR(&message);
0070|    header->cmsg_level = SOL_SOCKET;
0071|    header->cmsg_type = SCM_RIGHTS;
0072|    header->cmsg_len = CMSG_LEN(sizeof(int));
0073|    memcpy(CMSG_DATA(header), &listener, sizeof(int));
0074|    if (sendmsg((int)channel, &message, MSG_NOSIGNAL) != 4) return 126;
0075|    close(listener);
0076|    close((int)channel);
0077|    unsetenv("GUARDIAN_BROKER_FD");
0078|    execvp(argv[1], argv + 1);
0079|    return 127;
